insert into public.products (id, page_id, part_type, name, family, pro_rider, edition, entry_type,
  partner_page_id, disciplines, first_year, status, includes_frame, sort)
select v.id, p.id, v.part_type, v.name, v.family, v.pro_rider, v.edition, v.entry_type, pp.id,
  v.disciplines, v.first_year, v.status, v.includes_frame, v.sort
from catalog_seed v
join public.pages p on p.handle = v.handle
left join public.pages pp on pp.handle = v.partner
on conflict (id) do update set
  page_id = excluded.page_id, part_type = excluded.part_type, name = excluded.name,
  family = excluded.family, pro_rider = excluded.pro_rider, edition = excluded.edition,
  entry_type = excluded.entry_type, partner_page_id = excluded.partner_page_id,
  disciplines = excluded.disciplines, first_year = excluded.first_year, status = excluded.status,
  includes_frame = excluded.includes_frame, sort = excluded.sort,
  base_id = null;

-- Which model each pro model, collab and special edition builds on: the brand's
-- model with the same part type and name, if the catalog has it.
update public.products pr set base_id = b.id
from catalog_seed v, public.products b
where pr.id = v.id and pr.entry_type <> 'model'
  and b.page_id = pr.page_id and b.part_type = pr.part_type and b.entry_type = 'model'
  and lower(b.name) = lower(pr.name);

insert into public.product_notes (product_id, notes, sources)
select v.id, v.notes, v.sources from catalog_seed v
on conflict (product_id) do update set notes = excluded.notes, sources = excluded.sources;

-- Stock parts: replaced by what each product's row lists.
delete from public.product_stock_parts s using catalog_seed v where s.product_id = v.id;
